script.setup:
// Lottie Web plays a hand-made animation (assets/bloom.json) with its canvas renderer into an
// offscreen canvas; WebGL takes each frame as a texture. The animation's layers are drawn in pure
// red, green and blue so the shader can recolor them, fold them into a kaleidoscope ring and
// feed the result back on itself for zooming, twisting echo trails.
const mod = await ctx.utils.import("https://cdn.jsdelivr.net/npm/lottie-web@5.13.0/build/player/esm/lottie_light_canvas.min.js");
const lottie = mod.default ?? mod;
const animationData = await (await fetch(ctx.assets["bloom.json"])).json();
const gl = ctx.gl, S = 512;
const canvas = document.createElement("canvas");
canvas.width = S; canvas.height = S;
const anim = lottie.loadAnimation({
  renderer: "canvas", loop: true, autoplay: false, animationData,
  rendererSettings: { context: canvas.getContext("2d"), clearCanvas: true, preserveAspectRatio: "xMidYMid meet" },
});
const tex = gl.createTexture();
gl.bindTexture(gl.TEXTURE_2D, tex);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
// Half-float trails fade smoothly; 8-bit ones would stall in bands.
const float = !!gl.getExtension("EXT_color_buffer_float");
const header = `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor;
uniform vec2 u_resolution; uniform float u_time;`;
const feedback = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `${header}
uniform sampler2D u_prev, u_lottie;
uniform float u_echo, u_twist, u_segments, u_spread, u_spin, u_size;
uniform vec3 u_colorA, u_colorB, u_colorC;
const float TAU = 6.2831853;
mat2 rot(float a){ float c = cos(a), s = sin(a); return mat2(c, -s, s, c); }
// The Lottie frame at point q (frame spans [-u_size, u_size]), recolored channel by channel.
vec4 bloom(vec2 q){
  vec2 uv = q / (2.0 * u_size) + 0.5;
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
  vec4 c = texture(u_lottie, vec2(uv.x, 1.0 - uv.y));
  return vec4(c.r * u_colorA + c.g * u_colorB + c.b * u_colorC, c.a);
}
void main(){
  vec2 p = (gl_FragCoord.xy - 0.5 * u_resolution) / u_resolution.y;
  // Echo: last frame, zoomed out a little and twisted, so trails stream outwards in a spiral.
  vec2 q = rot(u_twist * 0.03) * p * (1.0 - 0.006 - 0.012 * u_echo);
  vec3 prev = texture(u_prev, q * u_resolution.y / u_resolution + 0.5).rgb;
  // Trails cool towards the last color as they age.
  prev = mix(prev, dot(prev, vec3(0.33)) * u_colorC * 1.4, 0.03);
  // Kaleidoscope ring: fold the plane into mirrored wedges and place a copy in each.
  vec4 cur = vec4(0.0);
  if (u_segments > 1.5) {
    float seg = TAU / u_segments;
    vec2 k = rot(u_spin) * p;
    float a = atan(k.y, k.x), r = length(k);
    a = mod(a, seg); a = abs(a - seg * 0.5);
    vec2 f = vec2(cos(a), sin(a)) * r - vec2(u_spread, 0.0);
    cur = bloom(rot(-u_spin * 2.0) * f * 2.0);
  }
  vec4 center = bloom(p);
  cur = cur * (1.0 - center.a) + center;
  vec3 col = prev * u_echo * 0.985 * (1.0 - cur.a * 0.85) + cur.rgb;
  outColor = vec4(min(col, vec3(8.0)), 1.0);
}`);
const present = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `${header}
uniform sampler2D u_image; uniform vec3 u_colorC;
void main(){
  vec3 c = texture(u_image, v_uv).rgb;
  vec2 q = v_uv - 0.5; q.x *= u_resolution.x / u_resolution.y;
  vec3 bg = mix(u_colorC * 0.06 + 0.012, vec3(0.006), smoothstep(0.1, 0.9, length(q)));
  c = bg + c;
  c = c / (1.0 + c * 0.35);        // soft shoulder for stacked echoes
  outColor = vec4(pow(c, vec3(0.95)), 1.0);
}`);
Object.assign(ctx.state, { anim, canvas, tex, feedback, present, float, buffers: null, phase: 0 });

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, [w, h] = ctx.resolution;
// Our own clock, so Speed can change smoothly (and run backwards).
s.phase += ctx.dt * u.u_speed;
const total = s.anim.totalFrames;
s.anim.goToAndStop((((s.phase * s.anim.frameRate) % total) + total) % total, true);
gl.bindTexture(gl.TEXTURE_2D, s.tex);
gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, true);
gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, s.canvas);
gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
if (!s.buffers || s.buffers.width !== w || s.buffers.height !== h) {
  s.buffers = ctx.utils.createPingPong(w, h, s.float ? { internalFormat: gl.RGBA16F, type: gl.HALF_FLOAT } : {});
}
const common = { u_colorA: u.u_colorA, u_colorB: u.u_colorB, u_colorC: u.u_colorC };
gl.bindFramebuffer(gl.FRAMEBUFFER, s.buffers.write().framebuffer);
gl.viewport(0, 0, w, h);
gl.useProgram(s.feedback);
ctx.utils.bindTexture(s.feedback, "u_prev", s.buffers.read().texture, 0);
ctx.utils.bindTexture(s.feedback, "u_lottie", s.tex, 1);
ctx.utils.drawFullscreen(s.feedback, { ...common, u_echo: u.u_echo, u_twist: u.u_twist, u_segments: u.u_segments,
  u_spread: u.u_spread, u_spin: ctx.time * 0.15, u_size: 0.26 });
s.buffers.swap();
gl.bindFramebuffer(gl.FRAMEBUFFER, null);
gl.viewport(0, 0, w, h);
gl.useProgram(s.present);
ctx.utils.bindTexture(s.present, "u_image", s.buffers.read().texture, 0);
ctx.utils.drawFullscreen(s.present, common);
ctx.publish("lottie frame", Math.floor(s.anim.currentFrame));
